css:
.projects-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 24px; }
.project-card {
  background: var(--bg-alt); border: 1px solid var(--border); border-radius: 20px; overflow: hidden;
  display: block; color: inherit; text-decoration: none; transition: border-color 0.25s ease;
}
.project-card:hover { color: inherit; border-color: var(--border-alt); }
.project-card.no-link { cursor: default; }

.project-visual { position: relative; aspect-ratio: 16/10; overflow: hidden; background: var(--bg); }
.project-img { width: 100%; height: 100%; object-fit: cover; object-position: top center; display: block; transition: transform 0.5s ease; }
.project-card:hover .project-img { transform: scale(1.05); }

.project-visual--placeholder {
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(circle at 30% 20%, rgba(14, 165, 233, 0.18), transparent 60%), var(--bg);
}
.project-placeholder-icon { color: var(--accent); opacity: 0.85; }

.project-info { padding: 24px 28px; display: flex; justify-content: space-between; align-items: flex-end; gap: 12px; }
.project-tag { font-family: 'JetBrains Mono', monospace; font-size: 11px; color: var(--accent); letter-spacing: 0.15em; text-transform: uppercase; margin-bottom: 8px; }
.project-title { font-family: 'Sora', sans-serif; font-weight: 700; font-size: 22px; letter-spacing: -0.02em; }
.project-note { font-family: 'JetBrains Mono', monospace; font-size: 10px; color: var(--text-dim); letter-spacing: 0.1em; text-transform: uppercase; margin-top: 8px; }
.project-arrow {
  width: 44px; height: 44px; border-radius: 50%; border: 1px solid #333; display: flex; align-items: center;
  justify-content: center; color: var(--accent); flex-shrink: 0;
}

@media (max-width: 900px) {
  .projects-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 700px) {
  .projects-grid { grid-template-columns: 1fr; gap: 20px; }
  .project-info { padding: 22px 24px; }
}
